 static Vector2 careScroll;static string careIdentity="";static int lastCareFrame=-2;
 public static void DrawCareMessage(Rect r,string message){message=PassengerPresentation.Speech(message);
  string key=message.Substring(0,Mathf.Min(16,message.Length));if(careIdentity!=key||Time.frameCount>lastCareFrame+1){careIdentity=key;careScroll=Vector2.zero;}lastCareFrame=Time.frameCount;
  var style=new GUIStyle(DrivingHudArt.Text(16,CasualUI.Ink,true)){wordWrap=true};float width=r.width-22,height=style.CalcHeight(new GUIContent(message),width);
  careScroll.y=Mathf.Clamp(careScroll.y,0,Mathf.Max(0,height-r.height));careScroll=GUI.BeginScrollView(r,careScroll,new Rect(0,0,width,Mathf.Max(r.height,height)),false,height>r.height);GUI.Label(new Rect(0,0,width,height),message,style);GUI.EndScrollView();
 }
